WITH dk AS ( SELECT id AS k, id AS doc_id FROM document UNION SELECT number AS k, id AS doc_id FROM document WHERE number IS NOT NULL ), pk AS ( SELECT id AS k, id AS pack_id FROM cr_pack UNION SELECT pack_number AS k, id AS pack_id FROM cr_pack WHERE pack_number IS NOT NULL ), mk AS ( SELECT id AS k, id AS meeting_id FROM meeting UNION SELECT label AS k, id AS meeting_id FROM meeting WHERE label IS NOT NULL ), mem AS ( SELECT DISTINCT dk.doc_id AS doc_id, pk.pack_id AS pack_id FROM (SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member) e JOIN dk ON dk.k = e.cr JOIN pk ON pk.k = e.pack_id ), mods AS ( SELECT DISTINCT dk.doc_id AS doc_id, e.section_id AS section_id FROM (SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by) e JOIN dk ON dk.k = e.cr ), disp AS ( SELECT DISTINCT dk.doc_id AS doc_id, d.code AS code, COALESCE(m.label, m.id) AS wg_meeting FROM disposition d JOIN dk ON dk.k = d.target JOIN resolution r ON r.id = d.resolution_id JOIN mk ON mk.k = r.meeting_id JOIN meeting m ON m.id = mk.meeting_id WHERE LOWER(REPLACE(REPLACE(REPLACE(TRIM(d.evidence_status),'_',''),'-',''),' ','')) IN ('sourceverified','verifiedsource','verifiedfromsource') AND LOWER(REPLACE(REPLACE(REPLACE(TRIM(d.scope),'_',''),'-',''),' ','')) IN ('wholedocument','document','whole','fulldocument','full','entiredocument','entire','doc','wholedoc','documentlevel','tdoc') AND LOWER(REPLACE(REPLACE(REPLACE(TRIM(m.wg),'_',''),'-',''),' ','')) IN ('ran5','r5','ranwg5','tsgranwg5','wg5') ), X AS ( SELECT id AS doc_id, target_release AS tr FROM document WHERE number = '{ANCHOR}' OR id = '{ANCHOR}' ), xs AS ( SELECT DISTINCT s.spec AS spec, s.release AS rel, s.clause AS clause FROM X JOIN mods ON mods.doc_id = X.doc_id JOIN section s ON s.id = mods.section_id WHERE LTRIM(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(TRIM(s.release)),'release',''),'rel',''),'-',''),' ',''),'r') = LTRIM(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(TRIM(X.tr)),'release',''),'rel',''),'-',''),' ',''),'r') ) SELECT DISTINCT xs.clause AS clause, COALESCE(d2.number, d2.id) AS document, disp.code AS disposition, disp.wg_meeting AS wg_meeting, COALESCE(cp.pack_number, cp.id) AS cr_pack FROM xs JOIN section s2 ON s2.spec = xs.spec AND s2.release = xs.rel AND s2.clause = xs.clause JOIN mods m2 ON m2.section_id = s2.id JOIN document d2 ON d2.id = m2.doc_id JOIN mem me2 ON me2.doc_id = d2.id JOIN cr_pack cp ON cp.id = me2.pack_id JOIN disp ON disp.doc_id = d2.id WHERE LTRIM(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(TRIM(d2.target_release)),'release',''),'rel',''),'-',''),' ',''),'r') = LTRIM(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(TRIM(s2.release)),'release',''),'rel',''),'-',''),' ',''),'r') AND d2.id NOT IN (SELECT doc_id FROM X) AND COALESCE(d2.number, '') <> '{ANCHOR}'
